INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('devops', 'datadog', 'overview', 'What is the key operational advantage of Datadog highlighted as the main tradeoff against its cost?', '["It requires no code changes for any feature", "Zero infrastructure to manage, with integrations for everything and AI-powered anomaly detection (Watchdog) -- at the cost of being expensive at scale", "It only works with Kubernetes workloads", "It replaces the need for any application logging"]', 1, 'The overview frames Datadog directly as a tradeoff: zero infrastructure to manage and broad integrations/anomaly detection, against real per-host cost at scale -- not a free lunch in either direction.', 'beginner'),
('devops', 'datadog', 'overview', 'What does enabling APM auto-instrumentation via admission.datadoghq.com/enabled: "true" actually give you?', '["Automatic scaling of the pod based on CPU", "Tracing injected into the pod (sidecar injection) with zero manual code changes required for basic instrumentation", "A guarantee that all requests are sampled at 100%", "Automatic log rotation for the container"]', 1, 'The Kubernetes annotation triggers auto-injection of the tracer via the admission controller -- distributed tracing without manually adding tracer code to the application.', 'intermediate'),
('devops', 'datadog', 'overview', 'What is Watchdog in Datadog?', '["A monitor for the Datadog Agent''s own uptime only", "AI-powered anomaly detection that automatically surfaces issues without manual alert threshold configuration", "A dedicated log shipping daemon", "The name of Datadog''s incident escalation policy"]', 1, 'Watchdog is explicitly described as AI-powered anomaly detection -- it surfaces anomalies automatically rather than requiring every alert threshold to be hand-configured.', 'beginner'),
('devops', 'datadog', 'overview', 'In the Helm install example, which flag is specifically needed so the Cluster Agent can expose an external metrics API (e.g. for HPA)?', '["datadog.logs.enabled=true", "datadog.apm.portEnabled=true", "clusterAgent.metricsProvider.enabled=true", "datadog.processAgent.enabled=true"]', 2, 'clusterAgent.metricsProvider.enabled=true is what makes the Cluster Agent expose Kubernetes custom/external metrics for consumers like the Horizontal Pod Autoscaler.', 'intermediate'),
('devops', 'datadog', 'overview', 'Why isn''t log-trace correlation automatic in Datadog by default, according to the overview''s example?', '["Datadog does not support log-trace correlation at all", "APM traces and application logs are two separate data streams by default -- the active trace''s ID has to be explicitly injected into each log line for the UI to link them", "Only Java applications support trace correlation", "Log-trace correlation requires a separate paid add-on"]', 1, 'The overview shows a custom logging formatter injecting dd.trace_id/dd.span_id into every log line specifically because traces and logs don''t correlate automatically without that link.', 'intermediate'),
('devops', 'datadog', 'fundamentals', 'Per the fundamentals comparison table, roughly what does Datadog cost compared to self-hosted Prometheus+Grafana?', '["Datadog is free; Prometheus+Grafana costs $15-35/host/month", "Datadog costs $15-35/host/month; Prometheus+Grafana is free (but requires self-hosting)", "Both cost the same per host", "Datadog charges only for storage, never for hosts"]', 1, 'The fundamentals table lists Datadog at $15-35/host/month versus Prometheus+Grafana being free (while requiring the team to self-host and operate it).', 'beginner'),
('devops', 'datadog', 'fundamentals', 'Which of the Four Golden Signals does the metric kubernetes.cpu.usage.total map to?', '["Latency", "Traffic", "Errors", "Saturation"]', 3, 'The fundamentals table maps kubernetes.cpu.usage.total to Saturation -- how full the system is -- distinct from latency, traffic, and errors.', 'beginner'),
('devops', 'datadog', 'fundamentals', 'What does prefixing a Python process start with ddtrace-run actually do?', '["It restarts the process automatically if it crashes", "It auto-instruments supported libraries like Flask, Django, requests, and psycopg2 without manual code changes", "It encrypts all outbound traffic from the process", "It disables APM sampling entirely"]', 1, 'ddtrace-run is Datadog''s auto-instrumentation entry point -- it patches supported libraries at process start so tracing works without manually wrapping every call site.', 'intermediate'),
('devops', 'datadog', 'fundamentals', 'What is a log-based metric used for, per the fundamentals log management section?', '["Converting all logs into traces automatically", "Turning a log search query into a first-class, graphable metric for something that was never emitted as a metric directly by the application", "Replacing the need for the Datadog Agent", "Reducing log retention costs to zero"]', 1, 'Log-based metrics let a log query (e.g. status:error service:payment-api) become a graphable metric -- useful for tracking something that only ever existed as log text, not an emitted metric.', 'intermediate'),
('devops', 'datadog', 'fundamentals', 'If Kubernetes pod/deployment metrics are missing from Datadog even though node-level Agent pods are healthy, what should be checked first per the troubleshooting guidance?', '["Whether DD_TRACE_SAMPLE_RATE is set too low", "Whether clusterAgent.metricsProvider.enabled is true, since the Cluster Agent (not the node Agent) is responsible for Kubernetes state metrics", "Whether the API key has expired", "Whether log exclusion filters are dropping the metrics"]', 1, 'The interview-question content explicitly calls out that pod/deployment metrics depend on the Cluster Agent being up and metricsProvider enabled -- node agents staying healthy doesn''t guarantee that.', 'advanced'),
('devops', 'datadog', 'intermediate', 'How does a single Datadog Monitor differ structurally from the separate Prometheus alerting-rule-plus-Alertmanager-routing setup?', '["A Monitor cannot send notifications, only Alertmanager can", "A Monitor combines the query, threshold, and notification targets into one resource, instead of splitting alerting rules and routing/notification config across two separate systems", "Monitors only support Slack notifications", "Monitors require a separate Alertmanager instance to function"]', 1, 'The content explicitly describes this as a real simplification: what Prometheus splits across a rule file and Alertmanager routing config, a Monitor combines into one resource -- at the cost of that reconciliation logic being managed by Datadog rather than visible/configurable like Alertmanager''s routing tree.', 'intermediate'),
('devops', 'datadog', 'intermediate', 'What is the stated real limitation of Watchdog''s AI-driven anomaly detection?', '["It only works for metrics, never for logs", "It can miss domain-specific anomalies that don''t look statistically unusual in isolation but matter given business context Watchdog has no visibility into -- it complements, not replaces, deliberately configured Monitors", "It cannot be disabled once enabled", "It requires manual threshold tuning identical to a regular Monitor"]', 1, 'The content is explicit that Watchdog is a complement to explicit Monitors on genuinely critical metrics, not a replacement -- it can miss anomalies that require business context it doesn''t have.', 'advanced'),
('devops', 'datadog', 'intermediate', 'What problem does managing Datadog dashboards via the Terraform provider ("dashboards as code") solve?', '["It makes dashboards load faster in the UI", "Dashboard drift -- someone tweaking a panel by hand with no review and nobody knowing why the change happened, once a team grows past one or two people", "It reduces the number of widgets allowed per dashboard", "It automatically generates SLOs from dashboard data"]', 1, 'The content frames dashboards-as-code specifically as a fix for drift: hand-edited dashboards in the UI don''t survive team growth, since changes go unreviewed and unexplained.', 'intermediate'),
('devops', 'datadog', 'intermediate', 'What is the real tradeoff of Datadog''s built-in SLO feature compared to a hand-rolled Prometheus SLO setup with manual recording rules?', '["Datadog SLOs cannot track error budgets at all", "Datadog''s built-in SLOs offer meaningfully less setup/maintenance overhead in exchange for less customization flexibility than a hand-rolled Prometheus setup", "Datadog SLOs are only available on the most expensive pricing tier", "Prometheus SLOs update in real time while Datadog SLOs only update daily"]', 1, 'The content states this explicitly as a real tradeoff: less customization flexibility, for meaningfully less setup and maintenance overhead versus a hand-rolled Prometheus multi-window burn-rate setup.', 'advanced'),
('devops', 'datadog', 'intermediate', 'How does the ddtrace logging integration''s patch() function differ from the overview''s manual dd.trace_id injection example?', '["patch() disables logging entirely during a trace", "patch() patches Python''s logging module directly so every log line emitted during an active trace is auto-correlated, without manually injecting dd.trace_id/dd.span_id into each log line", "patch() only works for JavaScript, not Python", "patch() replaces the need for the Datadog Agent"]', 1, 'The intermediate content contrasts this directly with Overview''s manual approach -- patch() automates the same correlation that Overview achieved by hand-writing a custom log formatter.', 'intermediate'),
('devops', 'datadog', 'advanced', 'In the SLO example targeting 99.9% availability over a rolling 30-day window, roughly how much "bad time" does the error budget allow per month?', '["About 4 hours", "About 43 minutes", "About 3 days", "Zero -- 99.9% means no downtime is ever allowed"]', 1, '0.1% of a 30-day window works out to roughly 43 minutes of allowed bad time per month -- the error budget is the actual, spendable inverse of the SLO target, not an abstract percentage.', 'advanced'),
('devops', 'datadog', 'advanced', 'Which DogStatsD metric type should be used to track current queue depth, and why would a Counter be the wrong choice?', '["A Counter, because queue depth only ever increases", "A Gauge, because it captures a current value at a point in time -- a Counter is increment-only and produces a monotonically increasing, meaningless chart for a value that goes up and down", "A Histogram, because queue depth needs percentile computation", "A Timing metric, because queue depth is measured in milliseconds"]', 1, 'The advanced content calls this out explicitly as a common mistake: using a Counter for something that should be a Gauge (queue depth) produces a monotonically increasing chart that''s meaningless, since queue depth naturally goes up and down.', 'advanced'),
('devops', 'datadog', 'advanced', 'What does the %%host%% template variable do in a Kubernetes Autodiscovery annotation?', '["It hardcodes a specific host''s IP address into the annotation", "It resolves to the pod''s actual IP at runtime, so the same annotation block works unchanged across every replica and every redeploy", "It disables Autodiscovery for that specific pod", "It forces the Agent to only monitor one replica"]', 1, '%%host%% is a runtime-resolved template variable -- the same static annotation config works across every pod replica because the Cluster Agent substitutes the real pod IP as pods appear.', 'advanced'),
('devops', 'datadog', 'advanced', 'In Datadog''s Incident Management workflow, what specifically triggers the automatic creation of an incident?', '["A manual button click by the on-call engineer", "A Monitor firing, rather than just generating a page -- this ties monitoring directly into the response process instead of treating alerting and incident coordination as separate systems", "A scheduled daily incident-review job", "An SLO breaching its warning threshold only, never its target threshold"]', 1, 'The content is explicit: a Monitor firing automatically creates an incident (not just a page), connecting the alerting and coordination systems that are otherwise disconnected.', 'intermediate'),
('devops', 'datadog', 'advanced', 'What mechanism in Datadog''s incident management workflow is described as mattering most operationally, and why?', '["The auto-generated postmortem draft alone, independent of anything else", "The auto-generated timestamped timeline of every action taken during the incident, since postmortems written from memory days later are reliably worse than ones assembled from a timestamped log of what was actually done", "The ability to page multiple people at once", "The JIRA ticket auto-creation integration"]', 1, 'The content specifically names the auto-generated timeline as the most operationally important mechanism -- it produces a postmortem grounded in a real timestamped record rather than reconstructed memory.', 'advanced'),
('devops', 'loki', 'overview', 'What does Loki index, in contrast to Elasticsearch?', '["The full text of every log line, same as Elasticsearch", "Only labels (metadata like namespace, app, pod) -- never the log content itself", "Only timestamps", "Nothing -- Loki performs no indexing at all"]', 1, 'Loki indexes only labels, not log content, which is exactly what makes it much cheaper than ELK for high-volume logs -- log content is stored separately as compressed chunks.', 'beginner'),
('devops', 'loki', 'overview', 'What is Promtail''s role in the Loki stack?', '["The query language used to search logs", "The log collection agent -- the equivalent of Filebeat in an ELK stack", "The Grafana panel type used to display logs", "The alerting component that evaluates LogQL rules"]', 1, 'Promtail is explicitly described as the log collection agent, analogous to Filebeat for ELK -- it ships logs, it doesn''t query or alert on them.', 'beginner'),
('devops', 'loki', 'overview', 'In the "three pillars of observability" framing, what question do traces specifically answer?', '["What is happening right now", "What happened and when", "Why is it slow -- by showing the full request path across services with timing", "How much does this cost to store"]', 2, 'The three pillars split is explicit: metrics answer ''what is happening now'', logs answer ''what happened and when'', and traces answer ''why is it slow'' via the full cross-service request path.', 'beginner'),
('devops', 'loki', 'overview', 'What specific failure mode does the NoPodLogs alert (absent(rate({namespace="production", app="payment-api"}[5m]))) catch that most teams forget to write an alert for?', '["A specific error message appearing too often in logs", "The absence of expected log volume entirely -- a service that has silently stopped emitting anything at all, rather than emitting logs with bad content", "High memory usage on the Promtail DaemonSet", "A malformed JSON log line"]', 1, 'The content calls this out directly: NoPodLogs is the alert teams forget to write because it fires on absence, catching a crash-looped or dead service that stopped logging entirely -- a different failure mode from bad-content alerting.', 'intermediate'),
('devops', 'loki', 'overview', 'What is the OTel Collector''s role in an OpenTelemetry-based observability pipeline?', '["It replaces Grafana as the visualization layer", "It receives signals (metrics, logs, traces) from applications and routes them to any backend (Prometheus, Loki, Tempo, Datadog, Jaeger), vendor-neutral", "It is a drop-in replacement for the Loki database itself", "It only handles trace data, never metrics or logs"]', 1, 'The OTel Collector is described as the routing hub -- one SDK emits all three signal types, and the Collector routes them to whichever backend(s) are configured, without changing application code to switch backends.', 'intermediate'),
('devops', 'loki', 'fundamentals', 'What does the "P" stand for in the PLG stack (Loki''s stack)?', '["Prometheus", "Promtail", "Pipeline", "Parser"]', 1, 'PLG stands for Promtail (collector) -> Loki (storage/query) -> Grafana (visualization) -- all three integrate natively.', 'beginner'),
('devops', 'loki', 'fundamentals', 'Per the fundamentals comparison table, roughly what fraction of raw log volume does Elasticsearch''s full-text index typically consume?', '["1-2%", "20-30%", "70-80%", "Elasticsearch does not build an index at all"]', 1, 'The table states Elasticsearch''s index is commonly 20-30% of raw log volume, since every word becomes searchable -- this is exactly the storage cost Loki avoids by indexing only labels.', 'intermediate'),
('devops', 'loki', 'fundamentals', 'In LogQL, what does the |= operator do in a query like {app="payment"} |= "ERROR"?', '["Excludes lines containing the given text", "Filters to log lines that contain the given text (a text/grep filter)", "Parses the log line as JSON", "Converts the query result into a metric"]', 1, '|= is a text filter that keeps only lines containing the given substring -- the LogQL equivalent of grep, applied after the label stream selector.', 'beginner'),
('devops', 'loki', 'fundamentals', 'What is the Ruler''s role in Loki, and what is it the equivalent of in the Prometheus ecosystem?', '["It routes logs to the correct index shard -- equivalent to a load balancer", "It evaluates LogQL rules and sends alerts on a schedule -- the logs equivalent of Prometheus''s rule evaluator/Alertmanager pairing", "It compresses log chunks before storage -- equivalent to gzip", "It authenticates incoming Promtail connections -- equivalent to an API gateway"]', 1, 'The Ruler evaluates LogQL metric queries on a schedule and fires alerts, described explicitly as the logs equivalent of how Prometheus evaluates PromQL rules and alerts.', 'intermediate'),
('devops', 'loki', 'fundamentals', 'What does the | json pipeline stage do in a LogQL query like {app="payment-api"} | json | level="error"?', '["It converts the entire result set into a downloadable JSON file", "It parses JSON-structured log lines into individual fields so they can be filtered on (like level) after the stream selector", "It deletes all non-JSON log lines from Loki permanently", "It re-indexes the log content for full-text search"]', 1, '| json parses structured JSON log lines into fields at query time, which is what allows a subsequent filter like level="error" to work against a specific parsed field.', 'beginner'),
('devops', 'loki', 'intermediate', 'What does the unwrap keyword do in LogQL (e.g. {service="api"} | json | unwrap duration | rate([5m]))?', '["It removes all labels from the query result", "It extracts a numeric field from a parsed log line and treats it as a value to aggregate, rather than just counting matching lines", "It decompresses a Loki chunk for manual inspection", "It disables rate limiting on the query itself"]', 1, 'unwrap is the mechanism that turns log content into a numeric aggregate -- extracting a parsed field''s value (like duration) so functions like rate() or quantile_over_time() can operate on the value, not just the line count.', 'intermediate'),
('devops', 'loki', 'intermediate', 'How can a service get a real P99 latency figure in Loki even if it never emitted a dedicated latency metric?', '["It cannot -- Loki requires a pre-defined metric for any percentile calculation", "unwrap plus quantile_over_time derives the P99 after the fact from a structured duration field the service already logs, without needing a separate metrics pipeline", "By manually calculating it in a spreadsheet from exported logs", "By switching the section to use Prometheus instead of Loki"]', 1, 'The content shows exactly this pattern: quantile_over_time(0.99, {service="api"} | json | unwrap duration [5m]) derives a real P99 from logs already being written for other reasons.', 'advanced'),
('devops', 'loki', 'intermediate', 'In the Loki retention configuration example, why does setting retention_period: 30d alone not actually delete logs older than 30 days?', '["retention_period only applies to metrics, not logs", "The compactor''s retention_enabled: true is also required -- retention_period alone does nothing without it actually enabling deletion", "Retention can only be configured via the Grafana UI, never in config files", "Loki has no retention mechanism at all"]', 1, 'The content flags this explicitly as a common early misconfiguration: retention needs both limits_config''s retention_period AND the compactor''s retention_enabled: true set together.', 'advanced'),
('devops', 'loki', 'intermediate', 'What is max_streams_per_user specifically a safety net against?', '["Slow queries caused by an overly broad time range", "A label-cardinality mistake (like promoting request_id to a label) turning into a full Ingester OOM -- new streams are rejected once the cap is hit, rather than silently accepted", "Unauthorized users querying the Loki API", "Promtail sending duplicate log lines"]', 1, 'max_streams_per_user is described as a blunt but effective cardinality safety net -- it surfaces a cardinality problem as an explicit rejection error instead of a slow-building memory crisis.', 'advanced'),
('devops', 'loki', 'intermediate', 'Why is the loki-stack bundled Helm chart described as not the best fit for production at real scale?', '["It does not support Kubernetes at all", "It''s deliberately optimized for getting something running quickly, not for independently scaling ingestion load versus query load -- the distributed/microservices mode is the better fit at real scale", "It only supports a single log source", "It requires a paid Grafana Cloud subscription to function"]', 1, 'The content explicitly frames loki-stack as fast-to-evaluate but not the production-scale answer, since it can''t independently scale ingestion versus query load the way microservices mode can.', 'intermediate'),
('devops', 'loki', 'advanced', 'Once auth_enabled: true is set for Loki multi-tenancy, how is one team''s logs actually isolated from another''s?', '["Only by convention -- teams are trusted not to query each other''s logs", "The tenant ID from the X-Scope-OrgID header is part of how chunks are indexed and retrieved -- a query from one tenant physically cannot return another tenant''s log streams, not just an application-level filter that could be bypassed", "By running a completely separate Loki binary per tenant automatically", "By encrypting each tenant''s logs with a different key that only Grafana can decrypt"]', 1, 'The content is explicit that this is real isolation baked into indexing/retrieval via the tenant ID, not a filter layered on top that a bug could bypass.', 'advanced'),
('devops', 'loki', 'advanced', 'In Loki''s distributed (microservices) mode, which component receives incoming log streams, validates them, and fans them out to Ingesters?', '["The Querier", "The Compactor", "The Distributor", "The Query Frontend"]', 2, 'The Distributor is specifically the write-path entry point -- it receives and validates incoming streams and fans them out to Ingesters, which then buffer and flush chunks.', 'advanced'),
('devops', 'loki', 'advanced', 'What is the "scalable monolith" deployment mode a middle ground between?', '["Development mode and a fully managed Grafana Cloud instance", "Single-binary mode (one process, doesn''t scale independently) and full microservices mode -- it runs multiple replicas of the single binary behind a load balancer", "LogQL and PromQL query languages", "Loki and Elasticsearch as competing products"]', 1, 'Scalable monolith keeps the single-binary deployment model but runs multiple replicas behind a load balancer -- horizontal scaling without the full operational complexity of six separately-managed microservices.', 'advanced'),
('devops', 'loki', 'advanced', 'Why can getting the tsdb_shipper local directory/cache configuration wrong cause degraded query performance, even with a correct S3 storage setup?', '["Because S3 alone cannot store log chunks reliably", "Because durable chunks live in S3, but TSDB still needs a local directory for actively-written index files plus a cache location -- getting this pairing wrong is a common source of degraded query performance in an otherwise-correct S3 setup", "Because tsdb_shipper is deprecated and no longer functions", "Because S3 requires the entire index to be stored client-side"]', 1, 'The content flags this specific pairing (durable chunks in S3, but no working local index cache) as a genuine, common misconfiguration distinct from a broken S3 setup itself.', 'advanced'),
('devops', 'loki', 'advanced', 'What is described as the single biggest lever on LogQL query performance?', '["The number of Grafana panels querying Loki simultaneously", "How selective the label selector is -- it determines how many chunks get fetched from storage before any text filtering happens at all", "The compression algorithm used for chunks", "Whether the query uses upper or lower case in the search term"]', 1, 'The advanced content states this as a general principle: an under-selective label filter forces excessive chunk fetches, and no amount of query-side text-filter cleverness compensates for that.', 'advanced'),
('devops', 'splunk', 'overview', 'What does SPL stand for in Splunk?', '["Structured Programming Language", "Search Processing Language", "Splunk Pipeline Layer", "Standard Parsing Library"]', 1, 'SPL is Splunk''s own query language -- Search Processing Language -- used to search, filter, and transform indexed machine data.', 'beginner'),
('devops', 'splunk', 'overview', 'What is the role of a Splunk Indexer?', '["It only runs SPL queries and displays dashboards", "It receives data from forwarders, parses it, extracts fields, and stores it in Splunk''s own indexed format organized into time-based buckets", "It is a lightweight agent that runs on the data source host", "It manages user authentication and licensing only"]', 1, 'Indexers are the storage/parsing role -- receiving forwarded data, extracting fields, and storing it in time-bucketed indexes on disk, distinct from Forwarders (collection) and Search Heads (query execution).', 'beginner'),
('devops', 'splunk', 'overview', 'What is the core difference between Splunk Enterprise and Splunk Cloud Platform?', '["Enterprise is self-hosted (the organization runs and scales its own indexers/search heads); Cloud Platform is Splunk-managed SaaS", "Enterprise only supports Windows; Cloud Platform only supports Linux", "Cloud Platform is free; Enterprise always requires a paid license", "Enterprise cannot use SPL; only Cloud Platform supports SPL"]', 0, 'Splunk Enterprise is self-hosted -- the org operates its own indexers and search heads -- while Splunk Cloud Platform is Splunk''s own managed SaaS offering, at typically higher per-GB cost in exchange for not operating the platform.', 'beginner'),
('devops', 'splunk', 'overview', 'In the SPL snippet `index=web_logs | eval response_category=if(status>=500,"error","success") | stats count by response_category`, what does the eval command specifically do?', '["It aggregates events into summary counts", "It computes a new field (response_category) from an expression, without reducing or aggregating the event set", "It extracts a field using a regular expression", "It filters out events where status is missing"]', 1, 'eval computes a new per-event field from an expression -- here classifying status into error/success -- and does not aggregate; the subsequent stats command does the aggregation.', 'intermediate'),
('devops', 'splunk', 'overview', 'In the incident-response example `index=auth "203.0.113.45" | transaction user maxspan=30m | table user, duration, eventcount`, what does the transaction command do?', '["It deletes events older than 30 minutes", "It groups related events into a single logical ''session'' per user, spanning multiple raw log lines, bounded by a 30-minute maximum span", "It converts the search into a saved, scheduled search", "It joins data from a completely separate Splunk instance"]', 1, 'transaction groups related events (like a user''s login session) that span multiple raw log lines into one logical unit, useful for reconstructing a user''s full activity rather than seeing disconnected individual events.', 'advanced'),
('devops', 'splunk', 'fundamentals', 'What analogy does the fundamentals content use to explain how an SPL pipeline works?', '["A relational database join", "A Unix shell pipeline / assembly line, where each pipe stage does exactly one job to whatever comes from the stage before it", "A single monolithic SQL query with no intermediate steps", "A recursive function call"]', 1, 'The content explicitly frames SPL as an assembly line / Unix-pipeline analogy -- search is the intake filter, and each | stage (eval, rex, stats, sort) is a station that transforms what the previous stage handed it.', 'beginner'),
('devops', 'splunk', 'fundamentals', 'What can rex do that eval cannot?', '["rex can aggregate events into summary counts; eval cannot", "rex extracts a genuinely new field from unstructured raw text using a regular expression; eval only computes/transforms fields from data that already exists as structured fields", "rex sorts search results; eval filters them", "rex and eval are functionally identical, just different syntax"]', 1, 'rex is specifically for pulling a field out of raw, unstructured text via regex when no such field exists yet -- eval computes or transforms a value from fields (or literals) already present on the event.', 'intermediate'),
('devops', 'splunk', 'fundamentals', 'In `stats count, avg(response_time) as avg_rt, max(response_time) as max_rt by host`, what does the `by host` clause do?', '["It filters events to only those from a host named ''host''", "It groups the aggregation (count, avg, max) separately for each distinct value of the host field", "It sorts the final results alphabetically by host", "It excludes the host field from the output entirely"]', 1, 'by host groups the stats aggregation per distinct host value -- producing one row of count/avg/max per host rather than one aggregate across all events.', 'beginner'),
('devops', 'splunk', 'fundamentals', 'What does the dc() function compute in `stats dc(user) as unique_users by host`?', '["The total count of all events, regardless of duplicates", "The distinct count -- how many unique values of the user field appear, per host", "The average value of the user field", "The difference between the current and previous count"]', 1, 'dc() is Splunk''s distinct-count aggregation function -- it answers ''how many unique X'' questions, here unique users per host.', 'intermediate'),
('devops', 'splunk', 'fundamentals', 'Why does the order of eval before stats matter in an SPL pipeline, per the fundamentals interview content?', '["It doesn''t matter -- SPL commands can be freely reordered without changing results", "stats can only group by fields that already exist on the events reaching it -- if a field needs to be computed by eval first, eval must run before stats collapses the individual events", "eval always runs last regardless of where it''s placed in the pipeline", "Order only matters for performance, never for correctness"]', 1, 'The content is explicit: a pipeline that tries to eval a field after stats already collapsed the data either fails to find the source fields or computes something meaningless from the aggregated rows.', 'advanced'),
('devops', 'splunk', 'intermediate', 'What is created in Splunk Enterprise Security specifically when a scheduled correlation search''s alert condition fires?', '["A plain email notification only, with no other record", "A Notable Event -- a structured, triaged, assignable record with its own workflow (status, owner, disposition), instead of just a search result or raw notification", "A new index created automatically for that alert type", "A permanent ban on the source IP that triggered it"]', 1, 'In Enterprise Security, a firing correlation search can create a Notable Event -- a structured record with a real triage workflow, not just a raw alert notification.', 'intermediate'),
('devops', 'splunk', 'intermediate', 'What is the key difference between a CSV lookup and a KV Store lookup?', '["CSV lookups are faster in every case than KV Store lookups", "A CSV lookup is a static uploaded file; a KV Store lookup is backed by Splunk''s built-in MongoDB-based store, useful when reference data changes frequently and needs updating via the REST API rather than re-uploading a file", "KV Store lookups can only be used with SPL''s stats command", "CSV lookups require a paid Enterprise Security license"]', 1, 'The content distinguishes them by mutability: CSV is a static file re-upload, while KV Store is a dynamic, programmatically updatable backing store for reference data that changes often.', 'advanced'),
('devops', 'splunk', 'intermediate', 'When is defining a field extraction via props.conf/transforms.conf preferable to using rex in every search?', '["Never -- rex is always the correct approach for any extraction", "Once a field is used often enough across many searches that recomputing it via rex every single time is wasteful -- this is a genuine performance decision, not just a stylistic one", "Only when the field contains numeric data", "Only for fields used in exactly one specific dashboard"]', 1, 'The content frames this as a performance tradeoff: rex is fine for ad hoc/exploratory extraction, but a props.conf extraction avoids repeatedly recomputing the same regex across every search against a high-volume index.', 'advanced'),
('devops', 'splunk', 'intermediate', 'What is a real operational risk of subsearches, per the content?', '["Subsearches can never be used with the outer search''s time range", "Subsearches have a default result limit and time budget -- one that returns too many results or runs too long gets silently truncated rather than erroring loudly", "Subsearches automatically delete the outer search''s results", "Subsearches require a separate Splunk license to run"]', 1, 'The content specifically flags silent truncation as the operational caveat -- a subsearch exceeding its default limits doesn''t error, it just quietly returns incomplete results, which is why stats-based joins are recommended for larger result sets.', 'advanced'),
('devops', 'splunk', 'intermediate', 'What is the relationship between a data model and Splunk''s drag-and-drop Pivot interface?', '["Pivot works directly on raw, unstructured events and doesn''t need a data model at all", "Pivot doesn''t understand raw unstructured events -- only the structured fields a data model exposes -- so the data model is the contract that makes Pivot possible for non-technical users", "Data models are only used for security use cases, never for Pivot", "Pivot replaces the need for data models entirely in newer Splunk versions"]', 1, 'The content is explicit: Pivot is aimed at users who need reports without writing SPL, and it can only operate against the structured, pre-defined fields a data model exposes -- not raw events directly.', 'intermediate'),
('devops', 'splunk', 'advanced', 'What is the difference between replication factor (RF) and search factor (SF) in Splunk indexer clustering?', '["RF and SF are two names for the exact same setting", "RF is how many total copies of each data bucket exist across the cluster (durability); SF is how many of those copies are immediately searchable (fast failover) -- SF is always less than or equal to RF", "SF controls durability; RF controls search speed only", "RF only applies to multi-site clusters, never single-site"]', 1, 'RF governs total copies for durability; SF governs how many of those copies are immediately query-ready. SF <= RF always, since a searchable copy is a strict superset requirement of a merely-replicated one.', 'advanced'),
('devops', 'splunk', 'advanced', 'Why can setting RF high but SF low be a real operational mistake?', '["It is never a mistake -- higher RF always improves search performance proportionally", "It protects data durability but doesn''t protect search performance during a node failure, since the ''extra'' durable-only copies aren''t immediately query-ready and would need a rebuild first", "It causes Splunk to reject all incoming data until fixed", "It only affects licensing cost, never actual behavior"]', 1, 'The content calls this out as a common real mistake -- durability and search availability are separate guarantees, and a high RF with low SF protects one but not the other during a failure.', 'advanced'),
('devops', 'splunk', 'advanced', 'Why is tstats typically an order of magnitude faster than stats for the same logical aggregation?', '["tstats runs on a separate, dedicated cluster of servers", "tstats reads directly from Splunk''s pre-built tsidx (time-series index) files without retrieving or decompressing raw events at all, while stats must pull and decompress raw event data first", "tstats only searches the last 5 minutes of data by default", "stats always requires a data model, while tstats does not"]', 1, 'tstats operates purely against indexed tsidx structures, skipping the expensive raw-event retrieval/decompression step that stats requires -- the source of the substantial performance gap at scale.', 'advanced'),
('devops', 'splunk', 'advanced', 'What is the core mechanism behind Risk-Based Alerting (RBA) in Splunk Enterprise Security?', '["Every correlation search independently decides alert-or-not, exactly as without RBA", "Individual events contribute risk scores to specific entities (a user, host, or IP), accumulating over time across multiple low-confidence signals -- a Notable Event triggers when an entity''s accumulated risk score crosses a threshold, not from any single search alone", "RBA replaces all correlation searches with a single machine-learning model", "RBA only scores IP addresses, never users or hosts"]', 1, 'RBA''s core shift is accumulation: many individually low-confidence signals converging on the same entity is a stronger indicator than any one alone, and the entity''s crossing a risk threshold -- not one search catching everything -- is what triggers the Notable Event.', 'advanced'),
('devops', 'splunk', 'advanced', 'What actually happens when an ingest-based Splunk license''s daily volume is exceeded and violations accumulate within the rolling window?', '["All previously indexed data is permanently deleted", "Data continues to be indexed (nothing is lost), but the platform can block the ability to search that data until the violation clears -- a fully-ingesting deployment that can''t be queried", "The Splunk instance shuts down completely until a new license is purchased", "Only the oldest 10% of data becomes unsearchable"]', 1, 'The content flags this exact failure mode: license violations can trigger search restriction while ingestion continues, meaning a SOC analyst may be unable to query during precisely the high-ingest-volume event (a real incident) when they need it most.', 'advanced')
